args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?album ?releasedLex ?releasedDate WHERE {
  VALUES ?album { dbr:Don't_Freak_Me_Out dbr:Love_&_War_(BarlowGirl_album) }
  ?album dbp:released ?releasedLex .
  BIND(
    IF(
      DATATYPE(?releasedLex) = xsd:date,
      ?releasedLex,
      IF(
        DATATYPE(?releasedLex) = xsd:int,
        xsd:date(CONCAT(STR(?releasedLex), "-01-01")),
        xsd:date(CONCAT(REPLACE(STR(?releasedLex), ".*(\\d{4}).*", "$1"), "-01-01"))
      )
    ) AS ?releasedDate
  )
}
ORDER BY ?releasedDate

